import {STATUSES} from './model.js';
const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function shopBoard(parts,dateLabel){
 return `<div class="shop-board">${STATUSES.map((stage,index)=>{
  const rows=parts.filter(p=>p.status===stage).sort((a,b)=>Number(b.blocked)-Number(a.blocked)||Number(b.priority==='High')-Number(a.priority==='High')||(a.due||'9999').localeCompare(b.due||'9999'));
  const next=STATUSES[index+1],action=['Start preparing','Start cutting','Start finishing','Finish'][index];
  return `<section class="shop-lane lane-${index}"><h3><span>${stage}</span><span class="lane-count">${rows.length}</span></h3><div class="shop-lane-cards">${rows.length?rows.map(p=>`<article class="shop-card ${p.blocked?'is-blocked':''}"><div class="card-top"><span class="part-number">${escape(p.number||'No number')}</span><details class="card-menu"><summary aria-label="More actions for ${escape(p.name)}">···</summary><label>Move to<select data-status="${escape(p.id)}" aria-label="Stage for ${escape(p.name)}">${STATUSES.map(s=>`<option ${s===stage?'selected':''}>${s}</option>`).join('')}</select></label></details></div><button class="part-name" data-edit="${escape(p.id)}">${escape(p.name)}</button><div class="card-tags">${p.blocked?'<span class="blocked-tag">Blocked</span>':''}${p.priority==='High'?'<span class="priority-tag">High priority</span>':''}</div><div class="card-assignment"><span>${escape(p.owner||p.assignedTo||'Unassigned')}</span><span>Qty ${p.quantity}</span></div>${p.process?`<p class="card-process">${escape(p.process)}</p>`:''}${p.due?`<p class="card-due">Due ${escape(dateLabel(p.due))}</p>`:''}${p.blocked&&p.notes?`<p class="shop-note">${escape(p.notes)}</p>`:''}<div class="card-actions">${next?`<button class="shop-action" data-advance="${escape(p.id)}" data-next="${next}">${action}</button>`:'<span class="finished-label">✓ Finished</span>'}<button class="block-toggle ${p.blocked?'tag-active':''}" aria-pressed="${Boolean(p.blocked)}" data-block="${escape(p.id)}" aria-label="${p.blocked?'Unblock':'Block'} ${escape(p.name)}">${p.blocked?'Unblock':'Block'}</button></div></article>`).join(''):'<p class="lane-empty">No parts</p>'}</div></section>`;
 }).join('')}</div>`;
}
